// Decide what this run is (daily spotlight or weekly roundup), pick the tools, and write the texts.
const SITE = 'https://tayyabimam1.github.io/awesome-ai-agent-stack/';
const REPO = 'https://github.com/tayyabimam1/awesome-ai-agent-stack';
const input = $input.first().json;
const now = new Date();
const kind = (input.body && input.body.kind) || (now.getUTCDay() === 1 && now.getUTCHours() >= 15 ? 'weekly' : 'spotlight');
const data = await this.helpers.httpRequest({ url: SITE + 'data.json', json: true });
const store = $getWorkflowStaticData('global');
const k = (n) => (n >= 1000 ? Math.round(n / 1000) + 'k' : String(n));
const all = data.sections.flatMap((s) => s.blocks.flatMap((b) => (b.entries || []).filter((e) => e.u && e.s).map((e) => ({ name: e.n, stars: e.s, about: e.d, url: e.u, category: s.title }))));

let title, url, picks, context;
if (kind === 'weekly') {
  // new since the last weekly run; the first run has no snapshot, so it shows the most-starred tools
  const seen = new Set(store.seenRepos || []);
  const fresh = seen.size ? all.filter((e) => !seen.has(e.name)) : [];
  const unique = [...new Map((fresh.length >= 5 ? fresh : all).map((e) => [e.name, e])).values()].sort((a, b) => b.stars - a.stars);
  picks = unique.slice(0, 10);
  title = fresh.length >= 5 ? `${fresh.length} tools added to the Awesome AI Agent Stack this week` : 'The 10 most-starred open-source AI agent tools right now';
  url = SITE;
  context = fresh.length >= 5 ? 'New additions this week, most-starred first.' : 'The most-starred projects on the whole list.';
  store.seenRepos = [...new Set(all.map((e) => e.name))];
} else {
  const day = Math.floor(Date.now() / 86400000);
  const sections = data.sections.filter((s) => s.count >= 10);
  const sec = sections[day % sections.length];
  const entries = all.filter((e) => e.category === sec.title).sort((a, b) => b.stars - a.stars);
  // each time a category comes round again, show the next five tools (within its top 30)
  const start = (Math.floor(day / sections.length) * 5) % Math.max(1, Math.min(entries.length - 4, 26));
  picks = entries.slice(start, start + 5);
  title = `${sec.title}: ${sec.count} open-source tools, ranked by GitHub stars`;
  url = SITE + sec.slug + '.html';
  context = sec.tagline;
}

const names = picks.slice(0, 3).map((p) => p.name.split('/')[1]).join(', ');
const bullets = picks.map((p) => `- ${p.name} (${k(p.stars)} stars): ${p.about}`).join('\n');
let short = `${title.length < 90 ? title : title.split(':')[0]}. Includes ${names}.\n${url}`;
let long = `${title}\n\n${bullets}\n\nFull list: ${url}\nAll ${data.total.toLocaleString('en-US')} tools: ${SITE}`;
let source = 'template';
for (let attempt = 0; attempt < 3 && source === 'template'; attempt++) try {   // free gateways fail now and then
  const res = await this.helpers.httpRequest({
    method: 'POST', url: $env.FREELLMAPI_URL + '/chat/completions', json: true, timeout: 120000,
    headers: { Authorization: 'Bearer ' + $env.FREELLMAPI_KEY },
    body: {
      model: 'auto', temperature: 0.7, max_tokens: 1100,
      messages: [
        { role: 'system', content: 'You write social posts for "Awesome AI Agent Stack", a free open-source list of AI agent tools ranked by GitHub stars. Plain, specific, no hype words, no emoji, no hashtags, no invented facts: use only the tools and numbers given. Reply with JSON only: {"short": "...", "long": "..."}. "short" is one post under 240 characters that names 2 or 3 of the tools and ends with the link. "long" is a LinkedIn-style post of 80 to 160 words that opens with what this is, lists the tools with one plain line each, and ends with the link.' },
        { role: 'user', content: JSON.stringify({ headline: title, context, tools: picks, link: url }) },
      ],
    },
  });
  const text = (res.choices[0].message.content || '').replace(/<think>[\s\S]*?<\/think>/g, '');
  const j = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  const ok = (t, max) => typeof t === 'string' && t.includes(url) && t.length <= max && t.length > 40;
  if (ok(j.short, 280) && ok(j.long, 1900)) { short = j.short; long = j.long; source = 'llm'; }
} catch (e) { /* the template texts are used */ }

// weekly runs also get a full article (facts only, no model text) for dev.to
const article = kind !== 'weekly' ? null : {
  title,
  tags: ['ai', 'opensource', 'agents', 'llm'],
  markdown: `${context}\n\n` + picks.map((p, i) => `## ${i + 1}. [${p.name}](${p.url})\n\n${p.about}\n\n**${p.stars.toLocaleString('en-US')} stars** · ${p.category}`).join('\n\n') +
    `\n\n---\n\nThis is from [Awesome AI Agent Stack](${SITE}), a free map of ${data.total.toLocaleString('en-US')} open-source AI agent tools in ${data.sections.length} categories, ranked by GitHub stars. The source is on [GitHub](${REPO}).`,
};
return [{ json: { kind, title, url, picks, short, long, source, article, mode: ($env.PROMO_MODE || 'draft') === 'now' ? 'now' : 'draft', results: {} } }];

// Bluesky: needs BLUESKY_HANDLE and BLUESKY_APP_PASSWORD (Settings, App passwords).
const item = $input.first().json;
const results = { ...(item.results || {}) };
const live = item.mode === 'now';
if (!$env.BLUESKY_HANDLE || !$env.BLUESKY_APP_PASSWORD) results.bluesky = 'not configured';
else if (!live) results.bluesky = 'draft only';
else try {
  const pds = 'https://bsky.social/xrpc/';
  const s = await this.helpers.httpRequest({ method: 'POST', url: pds + 'com.atproto.server.createSession', json: true,
    body: { identifier: $env.BLUESKY_HANDLE, password: $env.BLUESKY_APP_PASSWORD } });
  // the link has to be marked by byte offsets to be clickable
  const at = item.short.indexOf(item.url);
  const start = Buffer.byteLength(item.short.slice(0, Math.max(at, 0)), 'utf8');
  const facets = at < 0 ? [] : [{ index: { byteStart: start, byteEnd: start + Buffer.byteLength(item.url, 'utf8') },
    features: [{ $type: 'app.bsky.richtext.facet#link', uri: item.url }] }];
  const r = await this.helpers.httpRequest({ method: 'POST', url: pds + 'com.atproto.repo.createRecord', json: true,
    headers: { Authorization: 'Bearer ' + s.accessJwt },
    body: { repo: s.did, collection: 'app.bsky.feed.post',
      record: { $type: 'app.bsky.feed.post', text: item.short, facets, createdAt: new Date().toISOString() } } });
  results.bluesky = 'posted ' + r.uri;
} catch (e) { results.bluesky = 'failed: ' + String(e.message).slice(0, 200); }
return [{ json: { ...item, results } }];

// Mastodon: needs MASTODON_URL and MASTODON_TOKEN (an access token with write:statuses).
const item = $input.first().json;
const results = { ...(item.results || {}) };
const live = item.mode === 'now';
if (!$env.MASTODON_URL || !$env.MASTODON_TOKEN) results.mastodon = 'not configured';
else if (!live) results.mastodon = 'draft only';
else try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: $env.MASTODON_URL.replace(/\/$/, '') + '/api/v1/statuses', json: true,
    headers: { Authorization: 'Bearer ' + $env.MASTODON_TOKEN }, body: { status: item.short, visibility: 'public' } });
  results.mastodon = 'posted ' + r.url;
} catch (e) { results.mastodon = 'failed: ' + String(e.message).slice(0, 200); }
return [{ json: { ...item, results } }];

// Discord: needs DISCORD_WEBHOOK_URL (channel settings, Integrations, Webhooks).
const item = $input.first().json;
const results = { ...(item.results || {}) };
const live = item.mode === 'now';
if (!$env.DISCORD_WEBHOOK_URL) results.discord = 'not configured';
else if (!live) results.discord = 'draft only';
else try {
  await this.helpers.httpRequest({ method: 'POST', url: $env.DISCORD_WEBHOOK_URL, json: true, body: { content: item.long.slice(0, 1990) } });
  results.discord = 'posted';
} catch (e) { results.discord = 'failed: ' + String(e.message).slice(0, 200); }
return [{ json: { ...item, results } }];

// Telegram: needs TELEGRAM_BOT_TOKEN (from @BotFather) and TELEGRAM_CHAT_ID (the channel, e.g. @mychannel).
const item = $input.first().json;
const results = { ...(item.results || {}) };
const live = item.mode === 'now';
if (!$env.TELEGRAM_BOT_TOKEN || !$env.TELEGRAM_CHAT_ID) results.telegram = 'not configured';
else if (!live) results.telegram = 'draft only';
else try {
  await this.helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + $env.TELEGRAM_BOT_TOKEN + '/sendMessage', json: true,
    body: { chat_id: $env.TELEGRAM_CHAT_ID, text: item.long.slice(0, 4000), disable_web_page_preview: false } });
  results.telegram = 'posted';
} catch (e) { results.telegram = 'failed: ' + String(e.message).slice(0, 200); }
return [{ json: { ...item, results } }];

// dev.to: weekly article. Needs DEVTO_API_KEY (Settings, Extensions). Saved as a draft unless DEVTO_PUBLISH=true.
const item = $input.first().json;
const results = { ...(item.results || {}) };
const live = item.mode === 'now';
if (!item.article) results.devto = 'weekly only';
else if (!$env.DEVTO_API_KEY) results.devto = 'not configured';
else if (!live) results.devto = 'draft only';
else try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://dev.to/api/articles', json: true,
    headers: { 'api-key': $env.DEVTO_API_KEY },
    body: { article: { title: item.article.title, body_markdown: item.article.markdown, tags: item.article.tags, published: $env.DEVTO_PUBLISH === 'true' } } });
  results.devto = (r.published ? 'published ' : 'saved as draft ') + r.url;
} catch (e) { results.devto = 'failed: ' + String(e.message).slice(0, 200); }
return [{ json: { ...item, results } }];

// Keep a log of the last 200 runs for the dashboard, and return the run summary.
const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.runs = [{ at: new Date().toISOString(), kind: item.kind, title: item.title, mode: item.mode, writtenBy: item.source, results: item.results }, ...(store.runs || [])].slice(0, 200);
return [{ json: { kind: item.kind, title: item.title, mode: item.mode, writtenBy: item.source, results: item.results, short: item.short, long: item.long } }];

// One row a day: stars, forks, watchers and list size; views and clones too when GITHUB_TOKEN can read traffic.
const REPO = 'tayyabimam1/awesome-ai-agent-stack';
const headers = { 'User-Agent': 'n8n-promo', Accept: 'application/vnd.github+json', ...($env.GITHUB_TOKEN ? { Authorization: 'Bearer ' + $env.GITHUB_TOKEN } : {}) };
const gh = (path) => this.helpers.httpRequest({ url: 'https://api.github.com/repos/' + REPO + path, headers, json: true });
const repo = await gh('');
const row = { date: new Date().toISOString().slice(0, 10), stars: repo.stargazers_count, forks: repo.forks_count, watchers: repo.subscribers_count, openIssues: repo.open_issues_count };
try { row.tools = (await this.helpers.httpRequest({ url: 'https://tayyabimam1.github.io/awesome-ai-agent-stack/data.json', json: true })).total; } catch (e) {}
if ($env.GITHUB_TOKEN) try {
  const [views, clones] = [await gh('/traffic/views'), await gh('/traffic/clones')];
  row.views14d = views.count; row.visitors14d = views.uniques; row.clones14d = clones.count;
} catch (e) { row.traffic = 'token cannot read traffic'; }
const store = $getWorkflowStaticData('global');
store.stats = [row, ...(store.stats || []).filter((r) => r.date !== row.date)].slice(0, 400);
return [{ json: row }];

// A plain HTML page: growth numbers and the run log.
const store = $getWorkflowStaticData('global');
const stats = store.stats || [], runs = store.runs || [];
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const latest = stats[0] || {}, weekAgo = stats.find((r) => r.date <= new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10)) || stats[stats.length - 1] || {};
const delta = (key) => (latest[key] != null && weekAgo[key] != null ? (latest[key] - weekAgo[key] >= 0 ? '+' : '') + (latest[key] - weekAgo[key]) + ' in 7 days' : '');
const tile = (label, key) => `<div class="tile"><div class="n">${esc(latest[key] ?? '-')}</div><div>${label}</div><small>${delta(key)}</small></div>`;
const series = stats.slice(0, 60).reverse();
let chart = '<p>The chart appears after two days of data.</p>';
if (series.length > 1) {
  const min = Math.min(...series.map((r) => r.stars)), max = Math.max(...series.map((r) => r.stars)), span = Math.max(1, max - min);
  const pts = series.map((r, i) => `${(i / (series.length - 1) * 580 + 10).toFixed(1)},${(110 - (r.stars - min) / span * 100).toFixed(1)}`).join(' ');
  chart = `<svg viewBox="0 0 600 120" role="img" aria-label="Stars over the last ${series.length} days"><polyline fill="none" stroke="#0969da" stroke-width="2" points="${pts}"/></svg><small>Stars, ${esc(series[0].date)} to ${esc(series[series.length - 1].date)}: ${min} to ${max}</small>`;
}
const runRows = runs.slice(0, 40).map((r) => `<tr><td>${esc(r.at.slice(0, 16).replace('T', ' '))}</td><td>${esc(r.kind)}</td><td>${esc(r.mode)}</td><td>${esc(r.title)}</td><td>${Object.entries(r.results || {}).map(([c, v]) => `<b>${esc(c)}</b>: ${esc(v)}`).join('<br>')}</td></tr>`).join('');
const statRows = stats.slice(0, 30).map((r) => `<tr><td>${esc(r.date)}</td><td>${esc(r.stars)}</td><td>${esc(r.forks)}</td><td>${esc(r.watchers)}</td><td>${esc(r.tools ?? '')}</td><td>${esc(r.views14d ?? '')}</td><td>${esc(r.visitors14d ?? '')}</td><td>${esc(r.clones14d ?? '')}</td></tr>`).join('');
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Promo dashboard</title>
<style>body{font:15px/1.5 system-ui,sans-serif;margin:0 auto;max-width:980px;padding:16px;color:#1f2328;background:#fff}h1{font-size:22px}h2{font-size:17px;margin-top:28px}
.tiles{display:flex;flex-wrap:wrap;gap:12px}.tile{border:1px solid #d1d9e0;border-radius:8px;padding:12px 16px;min-width:130px}.n{font-size:26px;font-weight:600}
small{color:#59636e}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid #d1d9e0;padding:6px 8px;text-align:left;vertical-align:top}.scroll{overflow-x:auto}svg{width:100%;height:auto;border:1px solid #d1d9e0;border-radius:8px}
@media(prefers-color-scheme:dark){body{background:#0d1117;color:#f0f6fc}.tile,td,th,svg{border-color:#3d444d}small{color:#9198a1}}</style></head><body>
<h1>Awesome AI Agent Stack: promo dashboard</h1>
<div class="tiles">${tile('GitHub stars', 'stars')}${tile('Forks', 'forks')}${tile('Watchers', 'watchers')}${tile('Tools listed', 'tools')}${tile('Views, 14 days', 'views14d')}${tile('Visitors, 14 days', 'visitors14d')}</div>
<h2>Stars</h2>${chart}
<h2>Runs (latest ${Math.min(40, runs.length)} of ${runs.length})</h2><div class="scroll"><table><tr><th>When (UTC)</th><th>Kind</th><th>Mode</th><th>Post</th><th>Channels</th></tr>${runRows || '<tr><td colspan="5">No runs yet.</td></tr>'}</table></div>
<h2>Daily numbers</h2><div class="scroll"><table><tr><th>Date</th><th>Stars</th><th>Forks</th><th>Watchers</th><th>Tools</th><th>Views 14d</th><th>Visitors 14d</th><th>Clones 14d</th></tr>${statRows || '<tr><td colspan="8">No data yet.</td></tr>'}</table></div>
</body></html>`;
return [{ json: { html } }];
